package mz.bam.seeky.android;

import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import java.io.IOException;

/** A single ambient player survives sheets and readers, and can also follow the TTS transport. */
public final class BackgroundAudioService extends Service implements SharedPreferences.OnSharedPreferenceChangeListener {
 static final String PLAY="seeky.background.PLAY",FOLLOW="seeky.background.FOLLOW",PAUSE="seeky.background.PAUSE",STOP="seeky.background.STOP",CHANNEL="seeky_background";
 static final int ID=108;static BackgroundAudioService instance;ReadingBackground background;ReadingAudioFocus audioFocus;SharedPreferences prefs;
 boolean manual,following,paused,foreground,desired,closed;
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();SleepTimer.watch(this,()->BackgroundAudioService.stop(this));instance=this;prefs=getSharedPreferences("reading_background",0);prefs.registerOnSharedPreferenceChangeListener(this);background=new ReadingBackground(this,true);background.changed=this::playerChanged;audioFocus=ReadingAudioFocus.get(this);getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel(CHANNEL,tr("Fundo de áudio"),NotificationManager.IMPORTANCE_LOW));registerReceiver(noisy,new IntentFilter(android.media.AudioManager.ACTION_AUDIO_BECOMING_NOISY));}
 String tr(String value){return AppLanguage.text(this,value);}
 public int onStartCommand(Intent i,int flags,int id){if(i==null){stopSelf();return START_NOT_STICKY;}try{String action=i.getAction();if(STOP.equals(action)){manual=following=false;desired=false;paused=false;background.pause();audioFocus.release(this);stopForeground(STOP_FOREGROUND_REMOVE);foreground=false;stopSelf();return START_NOT_STICKY;}if(PAUSE.equals(action)){paused=true;manual=following=false;}else if(PLAY.equals(action)){manual=true;paused=false;}else if(FOLLOW.equals(action)){following=true;paused=false;}else return START_NOT_STICKY;ensureForeground();sync();}catch(Exception error){AppDiagnostics.record(this,"background-service",error);stopSelf();}return START_NOT_STICKY;}
 void sync(){if(closed)return;desired=!paused&&(manual||following&&prefs.getBoolean("enabled",false))&&!prefs.getString("path","").isEmpty();if(desired){ensureForeground();if(!audioFocus.acquire(this,()->{paused=true;manual=following=false;sync();})){paused=true;desired=false;background.pause();notifyState();return;}background.play();}else{background.pause();audioFocus.release(this);if(!paused&&!manual){stopForeground(STOP_FOREGROUND_REMOVE);foreground=false;stopSelf();return;}}notifyState();}
 void playerChanged(){if(closed)return;if(background.unavailable){background.pause();paused=true;manual=following=false;desired=false;audioFocus.release(this);}notifyState();}
 void ensureForeground(){if(foreground)return;if(Build.VERSION.SDK_INT>=29)startForeground(ID,notification(),ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);else startForeground(ID,notification());foreground=true;}
 void notifyState(){if(!closed)getSystemService(NotificationManager.class).notify(ID,notification());}
 PendingIntent control(String action,int code){return PendingIntent.getForegroundService(this,code,new Intent(this,BackgroundAudioService.class).setAction(action),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 Notification notification(){String title=prefs.getString("name",tr("Fundo de áudio")),state=background!=null&&background.unavailable?tr("Escolha outro áudio de fundo"):!desired?tr("Pausado"):background!=null&&background.ready?tr("A tocar durante a leitura"):tr("A abrir áudio…");return new Notification.Builder(this,CHANNEL).setSmallIcon(R.drawable.ic_seeky_notification).setContentTitle(tr("Fundo de áudio")+" · "+title).setContentText(state).setOnlyAlertOnce(true).setOngoing(desired).setContentIntent(PendingIntent.getActivity(this,108,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).addAction(new Notification.Action.Builder(null,tr(desired?"Pausar":"Continuar"),control(desired?PAUSE:PLAY,109)).build()).addAction(new Notification.Action.Builder(null,tr("Parar fundo"),control(STOP,111)).build()).build();}
 final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){paused=true;manual=following=false;sync();}};
 public void onSharedPreferenceChanged(SharedPreferences p,String key){if(key.equals("enabled")||key.equals("path"))sync();}
 public void onDestroy(){SleepTimer.unwatch(this);closed=true;if(instance==this)instance=null;prefs.unregisterOnSharedPreferenceChangeListener(this);try{unregisterReceiver(noisy);}catch(Exception ignored){}audioFocus.release(this);background.close();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
 static boolean playing(){return instance!=null&&instance.desired;}
 static void play(Context c){try{c.startForegroundService(new Intent(c,BackgroundAudioService.class).setAction(PLAY));}catch(Exception e){AppDiagnostics.record(c,"background-start",e);android.widget.Toast.makeText(c,AppLanguage.text(c,"Não foi possível iniciar o fundo."),android.widget.Toast.LENGTH_LONG).show();}}
 static void stop(Context c){if(instance!=null)try{c.startService(new Intent(c,BackgroundAudioService.class).setAction(STOP));}catch(Exception e){AppDiagnostics.record(c,"background-stop",e);}}
 static void follow(Context c,boolean on){if(instance!=null){instance.following=on;if(on)instance.paused=false;instance.sync();}else if(on&&c.getSharedPreferences("reading_background",0).getBoolean("enabled",false))try{c.startForegroundService(new Intent(c,BackgroundAudioService.class).setAction(FOLLOW));}catch(Exception e){AppDiagnostics.record(c,"background-follow",e);}}
}
